{
	/* Core v5.3 Vol 3 Part F 3.4.2:
	 *
	 *         The server and client shall set ATT_MTU to the minimum of the
	 *         Client Rx MTU and the Server Rx MTU.
	 */
#if defined(CONFIG_BT_ATT_OVER_BR)
	if (bt_att_is_over_br(chan)) {
		return MIN(chan->br_chan.rx.mtu, chan->br_chan.tx.mtu);
	}
#endif

	return MIN(chan->chan.rx.mtu, chan->chan.tx.mtu);
}

static void att_timeout(struct k_work *work)
{
	char addr[BT_ADDR_LE_STR_LEN];
	struct k_work_delayable *dwork = k_work_delayable_from_work(work);
	struct bt_att_chan *chan = CONTAINER_OF(dwork, struct bt_att_chan,
						timeout_work);
	struct bt_conn *conn = chan->att->conn;
	int err;

	if (!conn) {
		LOG_ERR("conn is null");
		return;
	}

	if (conn->type == BT_CONN_TYPE_LE) {
		bt_addr_le_to_str(bt_conn_get_dst(conn), addr, sizeof(addr));
	} else if (conn->type == BT_CONN_TYPE_BR) {
		bt_addr_to_str(bt_conn_get_dst_br(conn), addr, sizeof(addr));
	}

	LOG_ERR("ATT Timeout for device %s. Disconnecting...", addr);


	if (sys_slist_is_empty(&att->chans)) {
		/* Init general queues when attaching the first channel */
		k_fifo_init(&att->tx_queue);
#if CONFIG_BT_ATT_PREPARE_COUNT > 0
		sys_slist_init(&att->prep_queue);
#endif
	}

	sys_slist_prepend(&att->chans, &chan->node);
}

static void bt_att_connected(struct bt_l2cap_chan *chan)
{
	struct bt_att_chan *att_chan = ATT_CHAN(chan);
	struct bt_l2cap_le_chan *le_chan;
	struct bt_conn *conn;

	LOG_DBG("chan %p conn %p", chan, chan->conn);

	atomic_set_bit(att_chan->flags, ATT_CONNECTED);

	k_work_init_delayable(&att_chan->timeout_work, att_timeout);

#if defined(CONFIG_BT_ATT_OVER_BR)
	if (bt_att_is_over_br(att_chan)) {
		struct bt_l2cap_br_chan *br_chan = BT_L2CAP_BR_CHAN(chan);
		struct bt_att_conn_cb *callback;

		LOG_DBG("chan %p cid 0x%04x", br_chan, br_chan->tx.cid);

	att_chan_mtu_updated(att_chan);
	bt_gatt_connected(conn);
}

static void bt_att_disconnected(struct bt_l2cap_chan *chan)
{
	struct bt_att_chan *att_chan = ATT_CHAN(chan);
	struct bt_att *att = att_chan->att;
	struct bt_l2cap_le_chan *le_chan;

	if (!att_chan->att) {
		LOG_DBG("Ignore disconnect on detached ATT chan");
		return;
	}

	att_chan_detach(att_chan);

	/* Don't reset if there are still channels to be used */
	if (!sys_slist_is_empty(&att->chans)) {
		return;
	}

	att_reset(att);
uint16_t bt_att_get_uatt_mtu(struct bt_conn *conn)
{
	struct bt_att_chan *chan, *tmp;
	struct bt_att *att;

	att = att_get(conn);
	if (!att) {
		return 0;
	}

	SYS_SLIST_FOR_EACH_CONTAINER_SAFE(&att->chans, chan, tmp, node) {
		if (!bt_att_is_enhanced(chan)) {
			return bt_att_mtu(chan);
		}
	}

	LOG_WRN("No UATT channel found in %p", conn);

	return 0;
}

